{
  "name": "angular-jig",
  "version": "0.0.0",
  "type": "module",
  "scripts": {
    "ng": "ng",
    "start": "ng serve",
    "build": "ng build",
    "watch": "ng build --watch --configuration development",
    "test": "ng test",
    "lint": "eslint src",
    "test:harness": "vitest run --config harness/vitest.config.mjs",
    "typecheck:harness": "tsc -p tsconfig.harness.json --noEmit",
    "check:responsive": "node harness/gate/check-responsive.mjs",
    "count": "node harness/counter/counter.mjs --root . src",
    "check:boot": "node harness/gate/check-boot.mjs",
    "firings": "node harness/driver/firing-rollup.mjs",
    "check:wiring": "node harness/counter/check-wiring.mjs --root . src",
    "check:interaction": "node harness/gate/check-interaction.mjs",
    "check:contrast": "node harness/gate/check-contrast.mjs",
    "build:digest": "node harness/driver/build-house-digest.mjs"
  },
  "private": true,
  "packageManager": "npm@11.0.0",
  "dependencies": {
    "@angular/cdk": "22.0.0",
    "@angular/common": "^22.1.0",
    "@angular/compiler": "^22.1.0",
    "@angular/core": "^22.1.0",
    "@angular/forms": "^22.1.0",
    "@angular/platform-browser": "^22.1.0",
    "@angular/router": "^22.1.0",
    "@ng-icons/core": ">=32.0.0 <34.0.0",
    "@ng-icons/lucide": ">=32.0.0 <34.0.0",
    "@spartan-ng/brain": "^1.4.1",
    "class-variance-authority": "^0.7.0",
    "clsx": "^2.1.1",
    "rxjs": "~7.8.0",
    "tailwind-merge": "^3.5.0",
    "tslib": "^2.3.0",
    "zod": "^4.5.4"
  },
  "devDependencies": {
    "@angular/build": "^22.1.7",
    "@angular/cli": "^22.1.7",
    "@angular/compiler-cli": "^22.1.0",
    "@spartan-ng/cli": "^1.4.1",
    "@tailwindcss/postcss": "^4.1.12",
    "angular-eslint": "^22.2.0",
    "eslint": "^10.9.1",
    "jsdom": "^28.0.0",
    "playwright": "^1.63.0",
    "postcss": "^8.5.3",
    "prettier": "^3.8.1",
    "stylelint": "^17.14.1",
    "stylelint-declaration-strict-value": "^1.12.1",
    "tailwindcss": "^4.1.12",
    "tw-animate-css": "^1.4.0",
    "typescript": "~6.0.2",
    "typescript-eslint": "^8.69.0",
    "vitest": "^4.0.8"
  }
}
