  --card: #ffffff;
  --card-foreground: #1b1e2b;
  --popover: #ffffff;
  --popover-foreground: #1b1e2b;
  /* muted surface */
  --secondary: #eef0f6;
  --secondary-foreground: #1b1e2b;
  --muted: #eef0f6;
  --muted-foreground: #5b6072;
  /* subtle hover background (distinct from --primary) */
  --accent: #eef0f6;
  --accent-foreground: #1b1e2b;
  --destructive: #e5484d;
  /* border / input */
  --border: #e4e7ef;
  --input: #e4e7ef;
  /* focus ring: amber at 35% */
  --ring: #d8891a59;

